#!/bin/bash
# Build the host-side OPC UA client natively (gcc) against the amalgamation
# generated by scripts/build.sh. This exercises the single-file build on the
# host side and gives us the client for the on-target demo round-trip.
#
#   scripts/build-host-client.sh [cmake-build-dir] [output-dir]
#
# Defaults: cmake-build-dir = <repo>/build/build (contains open62541.c/.h),
# output = <repo>/build/host. Requires: gcc, python3 (not needed here).
set -euo pipefail

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
BUILD="${1:-$REPO/build/build}"
OUT="${2:-$REPO/build/host}"

[ -f "$BUILD/open62541.c" ] && [ -f "$BUILD/open62541.h" ] || {
    echo "ERROR: $BUILD/open62541.c/.h not found — run scripts/build.sh first"
    exit 1
}
command -v gcc >/dev/null || { echo "ERROR: gcc not found"; exit 1; }

mkdir -p "$OUT"
echo "== building host client into $OUT =="
gcc -std=c99 -I"$BUILD" "$REPO/tools/host_client.c" "$BUILD/open62541.c" \
    -lm -lpthread -o "$OUT/host_client"
file "$OUT/host_client"
echo "HOST CLIENT OK: $OUT/host_client"
